        padding: 0;
    }

    table td.align-left {
        text-align: left;
    }

    table td.align-center {
        text-align: center;
    }

    table td.align-right {
        text-align: right;
    }

    h1 {
        font-size: 19px;
        line-height: 22px;
        color: #333333;
        font-weight: bold;
    }

    h2 {
        font-size: 16px;
        line-height: 18px;
        color: #333333;
        font-weight: bold;
    }

    .hr {
        height:1px;
        background-color:#ccc;
    }

    .mail-wrapper {
        background-color: #ffffff;
    }

    table.list-items {
        
        table-layout: fixed;
        line-height: inherit;
        font-size: inherit;
    }

    table.list-items .list-item-prefix {
        padding-right: 4px;
        text-align: left;
        vertical-align: top;
    }

    table.list-items .list-item {
        text-align: left;
        vertical-align: top;
    }

    .show-on-mobile {
        display: none;
        mso-hide: all; /* Outlook */
        max-height: 0; /* Gmail */
        overflow: hidden; /* Gmail */
    }

    @media (max-width: 414px) {
        .show-on-mobile {
            display: table !important;
            mso-hide: none !important; /* Outlook */
            max-height: none !important; /* Gmail */
        }
        .hide-on-mobile {
            display: none !important;
            mso-hide: all !important;
            max-height: 0 !important;
            overflow: hidden;
        }
    }

